// Procedural test sounds only. No game audio or user settings are included.
using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Runtime.CompilerServices;
using System.Text;
using System.Threading;
using System.Windows.Forms;
using SplatoonAudio;
using VGAudio.Containers.NintendoWare;
using VGAudio.Formats;
using VGAudio.Formats.Pcm16;

internal static class AudioTests {
    static int assertions;static string folder;
    static void Check(bool value,string message){assertions++;if(!value)throw new Exception(message);}
    static void Equal<T>(T expected,T actual,string message){Check(object.Equals(expected,actual),message+" (expected "+expected+", got "+actual+")");}
    static void Throws(Action action,string message){try{action();}catch(InvalidDataException){assertions++;return;}catch(InvalidOperationException){assertions++;return;}throw new Exception(message);}
    static void Wait(Func<bool> predicate,string message,int milliseconds=2000){var clock=Stopwatch.StartNew();while(!predicate()&&clock.ElapsedMilliseconds<milliseconds)Thread.Sleep(5);Check(predicate(),message);}
    static PcmAudio Tone(int channels=1,int frames=16000,int rate=32000){var data=new short[channels][];for(int c=0;c<channels;c++){data[c]=new short[frames];for(int i=0;i<frames;i++)data[c][i]=(short)(10000*Math.Sin(i*(440+c*110)*2*Math.PI/rate));}return new PcmAudio(rate,data);}
    static void U16(byte[] b,int p,int value){b[p]=(byte)value;b[p+1]=(byte)(value>>8);}
    static byte[] PcmBwav(PcmAudio pcm,bool loop=false){int start=Binary.Align(16+pcm.Channels.Length*76,64),size=Binary.Align(pcm.Frames*2,64);var result=new byte[start+size*pcm.Channels.Length];Buffer.BlockCopy(Encoding.ASCII.GetBytes("BWAV"),0,result,0,4);U16(result,4,0xfeff);U16(result,6,1);U16(result,14,pcm.Channels.Length);
        for(int c=0;c<pcm.Channels.Length;c++){int p=16+c*76;U16(result,p+2,pcm.Channels.Length==1?2:c);Binary.Put(result,p+4,(uint)pcm.Rate);Binary.Put(result,p+8,(uint)pcm.Frames);Binary.Put(result,p+12,(uint)pcm.Frames);Binary.Put(result,p+48,(uint)(start+c*size));Binary.Put(result,p+52,(uint)(start+c*size));Binary.Put(result,p+56,1);Binary.Put(result,p+60,loop?(uint)pcm.Frames:uint.MaxValue);Binary.Put(result,p+64,loop?(uint)(pcm.Frames/4):0);Buffer.BlockCopy(pcm.Channels[c],0,result,start+c*size,pcm.Frames*2);}return result;}
    static byte[] Bars(bool old=false,byte[] embedded=null){int count=3;using(var stream=new MemoryStream()){stream.Write(new byte[16+count*12],0,16+count*12);var meta=new int[count];var offsets=new int[count];for(int i=0;i<count;i++){meta[i]=(int)stream.Length;byte[] head=new byte[old?32:40];Buffer.BlockCopy(Encoding.ASCII.GetBytes("AMTA"),0,head,0,4);if(old){U16(head,6,0x0400);Binary.Put(head,24,32);}else Binary.Put(head,36,4);stream.Write(head,0,head.Length);if(old)stream.Write(Encoding.ASCII.GetBytes("STRG\0\0\0\0"),0,8);byte[] name=Encoding.UTF8.GetBytes("Test_"+i+"\0");stream.Write(name,0,name.Length);}
            for(int i=0;i<count;i++){while(stream.Length%64!=0)stream.WriteByte(0);offsets[i]=(int)stream.Length;byte[] bwav=i==0&&embedded!=null?embedded:PcmBwav(Tone(i==1?2:1,8000+i*2000),i==2);stream.Write(bwav,0,bwav.Length);}byte[] result=stream.ToArray();Buffer.BlockCopy(Encoding.ASCII.GetBytes("BARS"),0,result,0,4);Binary.Put(result,4,(uint)result.Length);Binary.Put(result,12,(uint)count);
            // Deliberately use a hash-table order different from physical payload order.
            int[] order={2,0,1};for(int i=0;i<count;i++){Binary.Put(result,16+i*4,(uint)(90+i));Binary.Put(result,16+count*4+i*8,(uint)meta[order[i]]);Binary.Put(result,16+count*4+i*8+4,(uint)offsets[order[i]]);}return result;}}
    static byte[] StreamAudio(PcmAudio pcm,bool loop=true){IAudioFormat format=new Pcm16FormatBuilder(pcm.Channels,pcm.Rate).Build();format=loop?format.WithLoop(true,pcm.Frames/4,pcm.Frames):format.WithLoop(false);return new BCFstmWriter(NwTarget.Cafe).GetFile(new AudioData(format),new BxstmConfiguration{LoopPointAlignment=1,RecalculateLoopContext=true,RecalculateSeekTable=true});}
    static byte[] Fwav(bool be){var bytes=new byte[232];Action<int,uint> put=(p,v)=>{Binary.Put(bytes,p,v);if(be)Array.Reverse(bytes,p,4);};Action<int,int> put16=(p,v)=>{U16(bytes,p,v);if(be)Array.Reverse(bytes,p,2);};Buffer.BlockCopy(Encoding.ASCII.GetBytes("FWAV"),0,bytes,0,4);put16(4,0xfeff);put16(6,64);put(12,(uint)bytes.Length);put16(16,2);put(24,64);put(36,192);Buffer.BlockCopy(Encoding.ASCII.GetBytes("INFO"),0,bytes,64,4);put(68,128);bytes[72]=1;put(76,32000);put(84,16);put(92,1);put16(96,0x7100);put(100,20);put16(112,0x1f00);put(116,0);Buffer.BlockCopy(Encoding.ASCII.GetBytes("DATA"),0,bytes,192,4);put(196,40);for(int i=0;i<16;i++)put16(200+i*2,i*1500-10000);return bytes;}
    static string Write(string name,byte[] bytes){string path=Path.Combine(folder,name);File.WriteAllBytes(path,bytes);return path;}
    static byte[] Payload(AudioDocument document,Track track){return Binary.Slice(document.Data,track.Start,track.End-track.Start);}
    static void SamePcm(PcmAudio a,PcmAudio b,string message){Equal(a.Rate,b.Rate,message+" rate");Equal(a.Channels.Length,b.Channels.Length,message+" channels");Equal(a.Frames,b.Frames,message+" samples");for(int c=0;c<a.Channels.Length;c++)Check(a.Channels[c].SequenceEqual(b.Channels[c]),message+" samples "+c);}
    static void Files(){
        foreach(bool old in new[]{false,true}){byte[] raw=Bars(old);string path=Write(old?"old.bars":"sounds.bars",raw);var doc=new AudioDocument(path);Equal(3,doc.Tracks.Count,"BARS track count");Equal("Test_2",doc.Tracks[0].Name,"Hash order is retained");Equal(12000,doc.Tracks[0].Frames,"BARS duration metadata");Equal(.375,doc.Tracks[0].Duration,"BARS duration");SamePcm(Tone(1,12000),doc.Decode(doc.Tracks[0]),"PCM BWAV decode");
            var compressed=new AudioDocument(Write(old?"old.bars.zs":"sounds.bars.zs",Zstd.Compress(raw)));Check(compressed.Data.SequenceEqual(raw),"Zstd roundtrip");SamePcm(doc.Decode(doc.Tracks[2]),compressed.Decode(compressed.Tracks[2]),"Raw/compressed equivalent");
            string extracted=Path.Combine(folder,old?"extracted-old":"extracted");doc.Extract(doc.Tracks,extracted);Equal(3,Directory.GetFiles(extracted).Length,"Only three extracted WAV files");Check(Directory.GetFiles(extracted).All(p=>p.EndsWith(".wav")),"No JSON or manifests");SamePcm(doc.Decode(doc.Tracks[0]),PcmAudio.ReadWave(Directory.GetFiles(extracted,"000_*.wav")[0]),"Extraction identical");
            doc.SetReplacement(doc.Tracks[0],Tone(2,22050,44100));byte[] rebuilt=AudioDocument.ReadArchive(doc.Build(s=>{}));var result=new AudioDocument("result.bars.zs",rebuilt);Equal(16000,result.Tracks[0].Frames,"Replacement rate matched");Equal(4000,result.Tracks[0].LoopStart,"Loop start ratio retained");Equal(16000,result.Tracks[0].LoopEnd,"Loop end retained");Equal(1,result.Tracks[0].Codec,"Replacement encoded to DSP");
            Check(Payload(doc,doc.Tracks[1]).SequenceEqual(Payload(result,result.Tracks[1])),"Unmodified payload retained");Check(doc.Data.Take(doc.Tracks.Min(t=>t.Start)).Where((b,i)=>!(i>=4&&i<8)&&!(i>=32&&i<36)&&!(i>=40&&i<44)&&!(i>=48&&i<52)).SequenceEqual(result.Data.Take(doc.Tracks.Min(t=>t.Start)).Where((b,i)=>!(i>=4&&i<8)&&!(i>=32&&i<36)&&!(i>=40&&i<44)&&!(i>=48&&i<52))),"Names, hashes, metadata retained");
            Check(result.Decode(result.Tracks[0]).Frames==16000,"DSP BWAV playback after save");Check(File.ReadAllBytes(path).SequenceEqual(raw),"Source unchanged");
        }
        foreach(bool zipped in new[]{false,true}){var raw=PcmBwav(Tone(2),true);string path=Write(zipped?"standalone.bwav.zs":"standalone.bwav",zipped?Zstd.Compress(raw):raw);var doc=new AudioDocument(path);SamePcm(Tone(2),doc.Decode(doc.Tracks[0]),"Standalone BWAV");Equal(zipped?".bwav.zs":".bwav",doc.Extension,"BWAV output type");doc.SetReplacement(doc.Tracks[0],Tone(1,11025,22050));string saved=doc.Save(Path.Combine(folder,"replaced"+doc.Extension+doc.Extension),s=>{});Check(!Path.GetFileName(saved).EndsWith(doc.Extension+doc.Extension),"No duplicate suffix");var result=new AudioDocument(saved);Equal(16000,result.Tracks[0].Frames,"BWAV replacement length");Equal(4000,result.Tracks[0].LoopStart,"BWAV loop position");var decoded=result.Decode(result.Tracks[0]);Check(decoded.Channels[0].SequenceEqual(decoded.Channels[1]),"Mono replacement duplicated to stereo");
            decoded.WriteWave(Path.Combine(folder,zipped?"replaced-compressed.wav":"replaced-plain.wav"));byte[] channelData=result.Data;uint crc=0xffffffff;for(int c=0;c<2;c++){int p=(int)Binary.U32(channelData,16+c*76+52);foreach(byte v in channelData.Skip(p).Take((16000+13)/14*8)){crc^=v;for(int k=0;k<8;k++)crc=(crc>>1)^((crc&1)!=0?0xedb88320u:0);}}Equal(crc^0xffffffff,Binary.U32(channelData,8),"BWAV checksum");
            Throws(()=>doc.Save(path,s=>{}),"Cannot overwrite source");Check(File.ReadAllBytes(path).SequenceEqual(zipped?Zstd.Compress(raw):raw),"BWAV source intact");}
        foreach(int channels in new[]{1,2,4,10})foreach(bool zipped in new[]{false,true}){byte[] raw=StreamAudio(Tone(channels));string path=Write("stream-"+channels+(zipped?".bfstm.zs":".bfstm"),zipped?Zstd.Compress(raw):raw);var doc=new AudioDocument(path);var audio=doc.Decode(doc.Tracks[0]);Equal(channels,audio.Channels.Length,"BFSTM channels");Equal(16000,audio.Frames,"BFSTM frames");Equal(32000,audio.Rate,"BFSTM rate");Equal(channels>2,doc.ReadOnly,"Multichannel readonly");Check(audio.Peaks().All(p=>p>=0&&p<=1),"Waveform bounds");
            if(channels<=2){doc.SetReplacement(doc.Tracks[0],Tone(1,11025,22050));var result=new AudioDocument("replaced.bfstm",AudioDocument.ReadArchive(doc.Build(s=>{})));Equal(16000,result.Tracks[0].Frames,"BFSTM replacement length");Equal(channels,result.Tracks[0].Channels,"BFSTM channel match");Equal(4000,result.Tracks[0].LoopStart,"BFSTM loop preserved");Equal(16000,result.Decode(result.Tracks[0]).Frames,"BFSTM replacement decodes");}else{Throws(()=>doc.SetReplacement(doc.Tracks[0],Tone()),"No destructive multichannel replacement");string extract=Path.Combine(folder,"stream-extract-"+channels);doc.Extract(doc.Tracks,extract);Equal(channels,PcmAudio.ReadWave(Directory.GetFiles(extract)[0]).Channels.Length,"All channels extracted");}}
        var nonloop=new AudioDocument("once.bfstm",StreamAudio(Tone(),false));nonloop.SetReplacement(nonloop.Tracks[0],Tone(1,8000));var once=new AudioDocument("once.bfstm",nonloop.Build(s=>{}));Equal(-1,once.Tracks[0].LoopEnd,"One-shot BFSTM stays nonlooping");
        foreach(bool be in new[]{false,true}){var older=new AudioDocument("older.bars",Bars(true,Fwav(be)));var audio=older.Decode(older.Tracks[1]);Check(!older.Tracks[1].CanReplace,"Older track readonly");Check(!older.ReadOnly,"Other BWAV tracks remain editable");Equal(16,audio.Frames,"FWAV frame count");Check(audio.Channels[0].SequenceEqual(Enumerable.Range(0,16).Select(i=>(short)(i*1500-10000))),"FWAV channel-table relative offsets and byte order");}
        var prefetch=PcmBwav(Tone(),true);U16(prefetch,12,1);Binary.Put(prefetch,24,32000);Binary.Put(prefetch,76,32000);Binary.Put(prefetch,80,20000);var partial=new AudioDocument("prefetch.bwav",prefetch);Equal(16000,partial.Decode(partial.Tracks[0]).Frames,"Prefetch decodes stored samples only");Check(partial.ReadOnly,"Prefetch replacement disabled");var mixed=new AudioDocument("mixed.bars",Bars(false,prefetch));mixed.SetReplacement(mixed.Tracks[2],Tone());Check(new AudioDocument("mixed.bars",AudioDocument.ReadArchive(mixed.Build(s=>{}))).Tracks[1].Prefetch,"Untouched prefetch metadata retained");
        foreach(string name in new[]{"name","name.bars","name.bars.zs","name.bars.zs.bars.zs"}){var doc=new AudioDocument("source.bars",Bars());Equal("name.bars.zs",Path.GetFileName(doc.NormalizeOutput(name)),"Suffix normalization");}
        Throws(()=>AudioDocument.ReadArchive(new byte[1]),"Truncated file rejected");Throws(()=>Zstd.Decompress(new byte[]{1,2,3,4}),"Invalid compressed file rejected");Throws(()=>new AudioDocument("bad.bwav",new byte[16]),"Invalid magic rejected");
        var truncated=PcmBwav(Tone());Array.Resize(ref truncated,100);Throws(()=>new AudioDocument("short.bwav",truncated).Decode(AudioDocument.Inspect(truncated,0,truncated.Length,0,"short")),"Truncated payload rejected");
        var shuffled=Bars();Write("preview.bars",shuffled);Write("preview.bars.zs",Zstd.Compress(shuffled));
    }
    static void Wave(){var pcm=Tone(2);SamePcm(pcm,PcmAudio.ReadWave(pcm.WaveBytes()),"WAV roundtrip");var mono=Tone().Match(44100,2);Equal(22050,mono.Frames,"Sinc resample count");Check(mono.Channels[0].SequenceEqual(mono.Channels[1]),"Stereo match");Check(mono.Match(32000,1).Frames==16000,"Back resample count");Throws(()=>PcmAudio.ReadWave(new byte[16]),"Non-WAV rejected");byte[] bad=pcm.WaveBytes();bad[20]=3;Throws(()=>PcmAudio.ReadWave(bad),"Float WAV rejected");Throws(()=>new PcmAudio(0,new[]{new short[1]}),"Bad sample rate rejected");
        var layers=new PcmAudio(32000,new[]{new short[5],new short[5],new short[]{30000,30000,30000,30000,30000}});Check(layers.Peaks().All(p=>p==0),"Waveform uses first stereo pair");double gain=3;byte[] loud=WavePlayer.Render(new PcmAudio(1000,new[]{new short[]{20000,-20000}}),0,2,ref gain,3);Equal(short.MaxValue,BitConverter.ToInt16(loud,0),"Positive gain saturates");Equal(short.MinValue,BitConverter.ToInt16(loud,2),"Negative gain saturates");gain=0;Check(WavePlayer.Render(layers,0,5,ref gain,0).Length==20,"Preview only sends two channels");
        var constant=new PcmAudio(32000,new[]{Enumerable.Repeat((short)1000,512).ToArray()});gain=1;byte[] ramp=WavePlayer.Render(constant,0,512,ref gain,3);Check(BitConverter.ToInt16(ramp,0)<1100&&BitConverter.ToInt16(ramp,1022)==3000,"Gain smoothly ramps");
    }
    static void Playback(){using(var player=new WavePlayer(true)){player.SetSource(Tone(2,64000));player.Volume=0;player.Play();Wait(()=>player.PositionFrames>1000,"Playback begins");long previous=player.PositionFrames;var watch=Stopwatch.StartNew();for(int i=0;i<3000;i++)player.Volume=(i%301)/100f;Check(watch.ElapsedMilliseconds<200,"Gain changes are nonblocking");Thread.Sleep(150);Check(player.PositionFrames>previous,"Gain does not reset playback");player.Pause();Wait(()=>player.State==2,"Pause works");long paused=player.PositionFrames;Thread.Sleep(70);Equal(paused,player.PositionFrames,"Paused position fixed");player.Seek(32000);Wait(()=>Math.Abs(player.PositionFrames-32000)<10,"Paused seek works");Equal(2,player.State,"Seek keeps paused state");player.Restart();Wait(()=>player.State==1&&player.PositionFrames<10000,"Restart immediately plays while paused");previous=player.PositionFrames;Thread.Sleep(200);Check(player.PositionFrames>previous+4000,"Worker advances with no UI processing");player.Seek(63000);Wait(()=>player.State==0&&player.PositionFrames==64000,"EOF stops exactly");player.Play();Wait(()=>player.State==1&&player.PositionFrames<10000,"Play after EOF restarts");player.Stop();Wait(()=>player.State==0&&player.PositionFrames==0,"Stop rewinds");Check(player.Error==null,"No simulated output errors");}
        if(WinWaveDevice.waveOutGetNumDevs()>0){using(var player=new WavePlayer()){player.Volume=0;player.SetSource(Tone(10,64000));player.Play();Wait(()=>player.PositionFrames>1000||player.Error!=null,"Real output responds");Check(player.Error==null,"Real 10-channel input plays on stereo output");long before=player.PositionFrames;Thread.Sleep(200);Check(player.PositionFrames>before,"Real output feeds while GUI blocked");player.Pause();Wait(()=>player.State==2,"Real output pauses");player.Restart();Wait(()=>player.State==1,"Real output restarts");}}else Console.WriteLine("SKIP: no hardware audio endpoint; simulated playback passed.");
    }
    static void Interface(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var form=new MainForm("Legacy",false)){form.ShowInTaskbar=false;form.Location=new Point(-30000,-30000);form.StartPosition=FormStartPosition.Manual;form.Show();Application.DoEvents();Equal("Legacy",form.ThemeName,"Legacy selected");Equal(Color.Black,form.BackColor,"Legacy is pure black");Check(!form.GuideVisible,"Legacy hides Quick Guide");Check(!form.UsesCustomFont,"Legacy has system font");foreach(var theme in Skin.All){form.ApplyTheme(theme.Name,false);Application.DoEvents();Equal(theme.Name,form.ThemeName,"Switch theme");Equal(!theme.Legacy,form.GuideVisible,"Guide hidden only in Legacy");Equal(!theme.Legacy,form.UsesCustomFont,"Custom font only for normal themes");}form.ApplyTheme("Legacy",false);form.WindowState=FormWindowState.Maximized;Application.DoEvents();form.WindowState=FormWindowState.Normal;Application.DoEvents();Check(form.Cursor==Cursors.Default,"No stuck resize cursor");form.Close();}InterfaceFont.Release();}
    [STAThread]static int Main(string[] args){Program.Setup();try{return Run(args);}catch(Exception e){Console.Error.WriteLine("FAIL: "+e);return 1;}}
    [MethodImpl(MethodImplOptions.NoInlining)]static int Run(string[] args){
        if(args.Length>1&&args[0]=="--probe"){foreach(string path in args.Skip(1)){var doc=new AudioDocument(path);Console.WriteLine(doc.Kind+": "+doc.Tracks.Count+" tracks");foreach(var track in doc.Tracks.Where((t,i)=>i==0||i==doc.Tracks.Count/2||i==doc.Tracks.Count-1)){var pcm=doc.Decode(track);Check(pcm.Rate==track.Rate&&pcm.Channels.Length==track.Channels&&pcm.Frames>0,"Real asset decodes");Console.WriteLine("  "+track.Name+": "+pcm.Frames+" samples, "+pcm.Rate+" Hz, "+pcm.Channels.Length+" channels");}}return 0;}
        folder=Path.GetFullPath(args.Length>0?args[0]:"test-fixtures");Directory.CreateDirectory(folder);Wave();Console.WriteLine("PASS WAV, channel matching, resampling and waveform");Files();Console.WriteLine("PASS BARS/BWAV/BFSTM raw/compressed, replacement, extraction and source protection");Playback();Console.WriteLine("PASS playback, live gain, pause, seek, restart and background feeding");Interface();Console.WriteLine("PASS all themes, Legacy font/guide/background and native window controls");Console.WriteLine("PASS "+assertions+" assertions");return 0;
    }
}
